let registered = false;

export function registerAppUiLiteralSources(): void {
  if (registered) return;
  registered = true;
  for (const value of FR_UI_LITERALS) registerUiLiteralTranslationSource(value, "fr");
  for (const value of EN_UI_LITERALS) registerUiLiteralTranslationSource(value, "en");
  for (const value of ES_UI_LITERALS) registerUiLiteralTranslationSource(value, "es");
}

export const APP_UI_LITERAL_COUNTS = Object.freeze({ fr: FR_UI_LITERALS.length, en: EN_UI_LITERALS.length, es: ES_UI_LITERALS.length, total: FR_UI_LITERALS.length + EN_UI_LITERALS.length + ES_UI_LITERALS.length });
